(() => {
  const clean = s => (s||'').replace(/\s+/g,' ').trim();
  const out = {};
  out.h1 = clean(document.querySelector('main h1')?.innerText);
  // details well
  const well = document.querySelector('#details, .asset-details, main .row .col-md-12 .well, main .well');
  const dls = [...document.querySelectorAll('main .well dl, main dl.dl-horizontal, main .details dl')];
  const dl = dls[0] || document;
  const pairs = [];
  const dts = [...dl.querySelectorAll('dt')];
  dts.forEach(dt => {
    let dd = dt.nextElementSibling;
    pairs.push([clean(dt.innerText), clean(dd ? dd.innerText : '')]);
  });
  const dts2 = [...document.querySelectorAll('main dt')];
  out.dtAll = dts2.map(dt => [clean(dt.innerText), clean(dt.nextElementSibling ? dt.nextElementSibling.innerText : '')]);
  // status line area after tabs
  const statusLabel = [...document.querySelectorAll('main label, main span.label, main .label')].map(e=>clean(e.innerText)).filter(t=>t);
  out.labels = statusLabel.filter(t=>/deployed|ready|pending|archived|out for/i.test(t));
  const statusTexts = [...document.querySelectorAll('main a, main span, main div, main strong')].filter(e=>e.children.length===0 && /ready to deploy|deployed/i.test(e.textContent)).map(e=>clean(e.textContent));
  out.statusTexts = [...new Set(statusTexts)];
  return out;
})()
